-- ========================================
-- SugarGuard 饮品数据库扩充脚本
-- ========================================
-- 用途：在 init_database.sql 基础上追加 200+ 条新饮品数据
-- 覆盖品牌：喜茶/奈雪的茶/瑞幸/星巴克/库迪/蜜雪冰城/霸王茶姬/7分甜/沪上阿姨/
--          茶百道/古茗/Tim Hortons/Manner/M Stand/Peet's/CoCo/一点点/
--          可口可乐/百事/农夫山泉/元气森林/王老吉/加多宝/红牛/东鹏/脉动/
--          蒙牛/伊利/君乐宝/味全/维他/统一/娃哈哈/旺仔 等
-- 使用：mysql -u root -p Android_health_db < insert_more_drinks.sql
-- ========================================

USE Android_health_db;
SET NAMES utf8mb4;

-- ========================================
-- 为防止品牌+名称的重复插入，使用 INSERT IGNORE
-- 字段含义：含糖(g/100ml)、热量(kcal/100ml)、容量(ml)、咖啡因(mg/100ml)、
--          脂肪(g/100ml)、蛋白质(g/100ml)、钠(mg/100ml)、健康分(0-100)
-- ========================================

