-- ========================================
-- 数据统计
-- ========================================
SELECT '========================================' as ' ';
SELECT CONCAT('扩充饮品数据导入完成! 当前饮品总数: ', COUNT(*)) AS 'Status' FROM drinks;
SELECT brand AS '品牌', COUNT(*) AS '条目数' FROM drinks GROUP BY brand ORDER BY COUNT(*) DESC LIMIT 30;
SELECT category AS '类别', COUNT(*) AS '条目数', ROUND(AVG(sugar_content),1) AS '平均糖分(g/100ml)',
       ROUND(AVG(health_score),1) AS '平均健康分'
FROM drinks GROUP BY category ORDER BY COUNT(*) DESC;
SELECT '========================================' as ' ';
